   const targets=d.participantRules.count===1?[undefined]:nearby.filter(id=>id!==c.id);
   for(const targetId of targets){if(d.personalScene&&targetId&&(activityRegistry.get(schedule.getCurrentActivity(targetId).activityId??'')?.type==='sleep'||interactions.getActive(targetId)||[...simulationActive].some(key=>get(key).definitionId!==d.id&&get(key).participantCharacterIds.includes(targetId))))continue;if(d.opportunityGroup&&!ignoreCooldown&&now()<(cooldowns.get('scene-group/'+d.opportunityGroup.id+'/'+id+'/'+(targetId??''))??0))continue;if(targetId&&!ignoreCooldown&&now()<(cooldowns.get(d.id+'/'+targetId)??0))continue;if(targetId&&(!world.hasCharacter(targetId)||world.getCharacterReadSnapshot(targetId).location!.movement||world.getCharacterReadSnapshot(targetId).location!.currentLocationId!==c.location!.currentLocationId))continue;const value={...ctx,actorId:id,targetId};if(conditions([...d.participantRules.conditions,...required],value)&&(ignoreCooldown||now()>=(cooldowns.get(d.id+'/'+id)??0)))return {ids:[id,...targetId?[targetId]:[]],locationId:c.location!.currentLocationId,ctx:value};}
