  const sequence=++serial,e:WorldEventInstance={id:'world-event/'+sequence,sequence,definitionId,...(ctx.domainType?{triggerEvidence:{domainId:ctx.domainId,domainType:ctx.domainType,domainOutcome:ctx.domainOutcome,combatResult:ctx.combatResult}}:{}),status:pending?'pending':scheduledAt>now()?'scheduled':'pending',scheduledAt,participantCharacterIds:chosen.ids,locationId:chosen.locationId,stageTransitions:0,causeEventIds:[],resultEventIds:[],triggerContextId:key,chainDepth:depth,effectIds:[],evidence:d.participantRules.count===0?['지역 집계 관찰자 기록','인물 효과·강제 참가 없음']:['조건 확인','실제 위치·출입 확인'],roll,visibility:causes.some(id=>get(id).visibility==='private')?'private':causes.some(id=>get(id).visibility==='restricted')&&d.visibility==='public'?'restricted':d.visibility,history:[]};instances.set(e.id,e);if(e.status==='pending')simulationActive.add(e.id);processed.set('instance/'+key,now());cooldowns.set(d.id,now()+d.cooldownMinutes);chosen.ids.forEach(id=>cooldowns.set(d.id+'/'+id,now()+d.participantCooldownMinutes));if(d.opportunityGroup)cooldowns.set('scene-group/'+d.opportunityGroup.id+'/'+chosen.ids[0]+'/'+(chosen.ids[1]??''),now()+d.opportunityGroup.cooldownMinutes);occurrences.set(d.id,(occurrences.get(d.id)??0)+1);counters.created++;for(const cause of causes)relate(cause,e.id,relation);if(pending){e.pendingConditions=structuredClone(required);e.evidence=['당사자 이동/조건 대기','재검사 조건: '+JSON.stringify(required)];scheduleStage(e,now()+5);notify();return structuredClone(e);}if(scheduledAt>now()){scheduleStage(e,scheduledAt);notify();return structuredClone(e);}e.occurredAt=now();setStatus(e,'active','발생 조건 충족');enterStage(e,d.stages[0].id);options.wake?.(chosen.ids);return structuredClone(e);
