 function apply(e:WorldEventInstance,effectsToApply:WorldEventDefinition['outcomeRules'][number]['effects'],suffix:string){if(!effectsToApply.length)return true;const id=e.id+'/'+suffix;if(e.effectIds.includes(id))return true;const result=effects.applyActionEffects({id,sourceType:'system',sourceId:e.id,actorCharacterId:e.participantCharacterIds[0],targetCharacterId:e.participantCharacterIds[1],occurredAt:now(),outcomeType:suffix,effects:effectsToApply.map(effect=>effect.type==='status_apply'?{...structuredClone(effect),status:{...structuredClone(effect.status),id:e.id+'/'+effect.status.id,sourceId:e.id}}:structuredClone(effect))});if(result.status!=='applied'&&result.status!=='already_applied'){setStatus(e,'failed','공통 효과 실패: '+JSON.stringify(result));return false;}e.effectIds.push(id);e.appliedEffects??=[];e.appliedEffects.push({id,changes:'changes' in result?structuredClone(result.changes??[]):effects.getActionOutcome(id)?.changes??[]});return true;}
