 function recordSceneDecision(e:WorldEventInstance){const scene=definition(e.definitionId).personalScene!,decision=e.sceneDecision!,choice=scene.choices.find(c=>c.id===decision.choiceId)!;effects.recordDomainEvent({id:e.id+'/scene-choice',sourceId:e.id,type:'PersonalSceneDecision',occurredAt:now(),actorCharacterId:e.participantCharacterIds[0],targetCharacterId:e.participantCharacterIds[1],locationId:e.locationId,visibility:'private',details:{worldEventId:e.id,definitionId:e.definitionId,outcomeType:choice.id,reason:scene.title+' · '+(decision.autonomous?scene.autonomous[choice.mode==='engage'?'cooperative':choice.mode==='withdraw'?'strained':'independent']:choice.label+' / '+choice.response)}});}
